CREATE TABLE IF NOT EXISTS `platform_settings` (`key` text PRIMARY KEY NOT NULL,`value` text NOT NULL,`updated_at` text NOT NULL);
CREATE TABLE IF NOT EXISTS `profiles` (`id` text PRIMARY KEY NOT NULL,`email` text NOT NULL,`role` text DEFAULT 'advertiser' NOT NULL,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_profiles_email` ON `profiles` (`email`);
CREATE TABLE IF NOT EXISTS `advertisers` (`id` text PRIMARY KEY NOT NULL,`user_id` text NOT NULL REFERENCES `profiles`(`id`),`slug` text NOT NULL,`display_name` text NOT NULL,`description` text,`website` text,`status` text DEFAULT 'active' NOT NULL,`highest_rank` integer,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_advertisers_slug` ON `advertisers` (`slug`);
CREATE INDEX IF NOT EXISTS `idx_advertisers_user` ON `advertisers` (`user_id`);
CREATE TABLE IF NOT EXISTS `real_world_providers` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`internal_name` text NOT NULL,`website` text,`contact_name` text,`contact_email` text,`active` integer DEFAULT true NOT NULL,`notes` text,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE TABLE IF NOT EXISTS `real_world_reward_types` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`slug` text NOT NULL,`provider_id` text REFERENCES `real_world_providers`(`id`),`public_provider_name` integer DEFAULT false NOT NULL,`qualifying_spend_required_cents` integer NOT NULL,`estimated_provider_cost_cents` integer NOT NULL,`currency` text DEFAULT 'usd' NOT NULL,`duration_seconds` integer NOT NULL,`estimated_plays` integer NOT NULL,`screen_name` text,`location_description` text,`minimum_lead_days` integer NOT NULL,`creative_requirements_json` text DEFAULT '{}' NOT NULL,`reward_repeat_mode` text DEFAULT 'first_reward_only' NOT NULL,`active` integer DEFAULT true NOT NULL,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_reward_types_slug` ON `real_world_reward_types` (`slug`);
CREATE TABLE IF NOT EXISTS `qualifying_spend_events` (`id` text PRIMARY KEY NOT NULL,`user_id` text NOT NULL,`advertiser_id` text NOT NULL,`payment_id` text,`bid_id` text,`amount_cents` integer NOT NULL,`currency` text DEFAULT 'usd' NOT NULL,`event_type` text NOT NULL,`qualifies_for_rewards` integer DEFAULT true NOT NULL,`created_at` text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_qse_payment_event` ON `qualifying_spend_events` (`payment_id`,`event_type`);
CREATE INDEX IF NOT EXISTS `idx_qse_advertiser_time` ON `qualifying_spend_events` (`advertiser_id`,`created_at`);
CREATE TABLE IF NOT EXISTS `real_world_rewards` (`id` text PRIMARY KEY NOT NULL,`user_id` text NOT NULL,`advertiser_id` text NOT NULL,`reward_type_id` text NOT NULL REFERENCES `real_world_reward_types`(`id`),`threshold_sequence` integer DEFAULT 1 NOT NULL,`status` text DEFAULT 'earned' NOT NULL,`earned_at` text NOT NULL,`creative_id` text,`requested_date_1` text,`requested_date_2` text,`requested_date_3` text,`confirmed_date` text,`provider_booking_reference` text,`estimated_provider_cost_at_earn_cents` integer NOT NULL,`actual_provider_cost_cents` integer,`rush_fee_cents` integer DEFAULT 0 NOT NULL,`rush_booking` integer DEFAULT false NOT NULL,`admin_notes` text,`completed_at` text,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_rewards_advertiser_type_sequence` ON `real_world_rewards` (`advertiser_id`,`reward_type_id`,`threshold_sequence`);
CREATE INDEX IF NOT EXISTS `idx_rewards_status` ON `real_world_rewards` (`status`);
CREATE TABLE IF NOT EXISTS `real_world_creatives` (`id` text PRIMARY KEY NOT NULL,`advertiser_id` text NOT NULL,`reward_id` text NOT NULL REFERENCES `real_world_rewards`(`id`),`file_url` text,`thumbnail_url` text,`headline` text,`destination_url` text,`brand_name` text,`domain` text,`background_color` text,`text_alignment` text,`font_size` integer,`template` text,`status` text DEFAULT 'draft' NOT NULL,`rejection_reason` text,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE INDEX IF NOT EXISTS `idx_rw_creatives_reward` ON `real_world_creatives` (`reward_id`);
CREATE TABLE IF NOT EXISTS `real_world_reward_evidence` (`id` text PRIMARY KEY NOT NULL,`reward_id` text NOT NULL REFERENCES `real_world_rewards`(`id`),`type` text NOT NULL,`file_url` text,`external_url` text,`notes` text,`created_at` text NOT NULL);
CREATE INDEX IF NOT EXISTS `idx_reward_evidence_reward` ON `real_world_reward_evidence` (`reward_id`);
INSERT OR IGNORE INTO `real_world_providers` (`id`,`name`,`internal_name`,`active`,`created_at`,`updated_at`) VALUES ('provider_default','Fulfillment partner','Initial Times Square partner',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
